'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=[...new Set(COURSES.map(c=>c.category))];const baseCourses=structuredClone(COURSES);
let user=null,server=false,csrfReady=false,state,current=null,lesson=0,mode='read',view='home',objectURLs=[],renderToken=0,saveQueue=Promise.resolve(),speechToken=0;
const blank=()=>({version:3,enrolled:[],completed:{},notes:{},bookmarks:[],attempts:{},plans:[],last:{},settings:{name:'Learner',theme:'light',font:16,mode:'read'},assignments:[]});
function key(){return user?'ethan-lms-user-'+user.id:'ethan-lms-v1'}
function cleanState(raw){const s=blank(),ids=new Set(COURSES.map(c=>c.id));if(!raw||typeof raw!=='object')return s;s.enrolled=[...new Set((Array.isArray(raw.enrolled)?raw.enrolled:[]).filter(x=>ids.has(x)))];s.bookmarks=[...new Set((Array.isArray(raw.bookmarks)?raw.bookmarks:[]).filter(x=>ids.has(x)))];for(const id of ids){const c=COURSES.find(c=>c.id===id),max=c.lesson_count||c.lessons?.length||3;if(raw.version===3&&Array.isArray(raw.completed?.[id]))s.completed[id]=[...new Set(raw.completed[id].filter(n=>Number.isInteger(n)&&n>=0&&n<max))];const last=raw.last?.[id];if(Number.isInteger(last)&&last>=0&&last<max)s.last[id]=last}
for(const[k,v]of Object.entries(raw.notes||{}))if(/^[a-zA-Z0-9_-]+-\d+$/.test(k)&&typeof v==='string')s.notes[k]=v.slice(0,20000);
for(const[k,a]of Object.entries(raw.version===3?raw.attempts||{}:{}))if(/^[a-zA-Z0-9_-]+-\d+$/.test(k)&&Array.isArray(a))s.attempts[k]=a.filter(x=>x&&typeof x.score==='number'&&x.score>=0&&x.score<=100&&typeof x.date==='string').slice(-50);
s.plans=(Array.isArray(raw.plans)?raw.plans:[]).filter(p=>p&&ids.has(p.course)&&typeof p.id==='string'&&typeof p.date==='string'&&/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(p.date)&&Number.isFinite(new Date(p.date).valueOf())).slice(0,200).map(p=>({id:p.id,course:p.course,date:p.date,duration:Math.min(240,Math.max(10,Number(p.duration)||30)),done:!!p.done}));
if(raw.settings&&typeof raw.settings==='object')s.settings={name:String(raw.settings.name||'Learner').slice(0,120),theme:['light','dark'].includes(raw.settings.theme)?raw.settings.theme:'light',font:[16,18,20].includes(Number(raw.settings.font))?Number(raw.settings.font):16,mode:['read','pdf','video','narrate','practice','quiz'].includes(raw.settings.mode)?raw.settings.mode:'read'};
s.assignments=(Array.isArray(raw.assignments)?raw.assignments:[]).filter(a=>a&&ids.has(a.course_id)&&Number.isInteger(a.lesson)&&typeof a.text==='string').slice(-100);return s}
function loadState(){try{state=cleanState(JSON.parse(localStorage.getItem(key())))}catch{state=blank()}applySettings()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
async function api(path,options={}){const r=await fetch('/api/'+path,{...options,headers:{...(options.body instanceof Blob?{}:{'Content-Type':'application/json'}),...options.headers}});if(!r.ok){let message;try{message=(await r.json()).error}catch{message='Server request failed'}throw Error(message)}return r.status===204?null:r.json()}
function save(){let ok=true;try{localStorage.setItem(key(),JSON.stringify(state))}catch{toast('Browser storage is full. Export a backup.');ok=false}if(user){const snapshot=JSON.stringify(state);saveQueue=saveQueue.catch(()=>{}).then(()=>api('state',{method:'PUT',body:snapshot})).catch(e=>{toast('Saved locally; server sync failed: '+e.message);return false})}return ok}
function applySettings(){document.documentElement.dataset.theme=state?.settings.theme||'light';document.documentElement.style.setProperty('--lesson-font',(state?.settings.font||16)+'px')}
function download(name,content,type='application/json'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function stopMedia(){speechToken++;if('speechSynthesis'in window)speechSynthesis.cancel();for(const u of objectURLs)URL.revokeObjectURL(u);objectURLs=[];document.querySelectorAll('video,audio').forEach(v=>v.pause())}
async function db(){return new Promise((res,rej)=>{const r=indexedDB.open('ethan-lms-resources',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function localResource(op,k,v){const d=await db();return new Promise((res,rej)=>{const tx=d.transaction('files',op==='get'||op==='list'?'readonly':'readwrite'),s=tx.objectStore('files');let result;const r=op==='list'?s.openCursor():op==='get'?s.get(k):op==='delete'?s.delete(k):s.put(v,k);if(op==='list'){result=[];r.onsuccess=()=>{const cursor=r.result;if(cursor){result.push({key:cursor.key,name:cursor.value.name,mime:cursor.value.type,size:cursor.value.size});cursor.continue()}}}else r.onsuccess=()=>result=r.result;tx.oncomplete=()=>{d.close();res(result)};tx.onerror=()=>{d.close();rej(tx.error)}})}
async function resource(op,k,file,owner=''){if(!user){if(owner==='shared')return null;return localResource(op,k,file)}const suffix=owner?owner+'/':'';if(op==='get'){const r=await fetch('/api/files/'+suffix+encodeURIComponent(k));if(r.status===404)return null;if(!r.ok)throw Error('Could not load resource');return new File([await r.blob()],r.headers.get('X-File-Name')||'resource',{type:r.headers.get('Content-Type')})}return api('files/'+suffix+encodeURIComponent(k),{method:op==='delete'?'DELETE':'PUT',...(op==='put'?{body:file,headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name)}}:{})})}
const starterTitles=['Understand the foundations','Plan a practical workflow','Build, test and reflect'];
function lessons(c){if(c.lessons?.length)return c.lessons;if(c.lesson_titles?.length)return c.lesson_titles.map(title=>({title,locked:true}));const d=categoryLessons[c.category];return starterTitles.map((title,n)=>({title,intro:`${c.title}: ${n===0?'learn the foundation':n===1?'plan a small practical task':'create and review your first result'}. This is a category-based introductory pathway, ready for expansion with specialist lessons.`,concept:d.concept,steps:d.steps,example:d.example,task:n===0?`Describe a real problem that ${c.title.toLowerCase()} could help solve. Define three relevant terms in your own words.`:n===1?`Plan a small ${c.title.toLowerCase()} project. List the inputs, tools, success criteria and testing steps.`:c.project,quiz:[{question:d.question,answers:d.answers,correct:0,explanation:d.concept},{question:'Which action belongs in the practical workflow for this lesson?',answers:[d.steps[n],'Skip testing and publish the first result','Choose tools without defining a goal'],correct:0,explanation:d.steps[n]},{question:'What makes a useful mastery review?',answers:['Demonstrating a result, checking it and explaining an improvement','Copying notes without understanding them','Marking a lesson complete before doing the task'],correct:0,explanation:'A review should provide evidence of understanding and practical work.'}]}))}
const cby=id=>COURSES.find(c=>c.id===id), noteKey=()=>current.id+'-'+lesson, best=(id,n)=>Math.max(0,...(state.attempts[id+'-'+n]||[]).map(a=>a.score));
function card(c){const count=lessons(c).length,done=(state.completed[c.id]||[]).length;return `<article class="course"><div class="courseart" style="background:${/^#[0-9a-f]{6}$/i.test(c.color)?c.color:'#e9f1ff'}"><strong>${esc(c.title.split(' ').map(w=>w[0]).slice(0,2).join(''))}</strong><button class="bookmark secondary" data-bookmark="${esc(c.id)}" aria-label="${state.bookmarks.includes(c.id)?'Remove bookmark':'Bookmark'} ${esc(c.title)}">${state.bookmarks.includes(c.id)?'★':'☆'}</button></div><div class="coursebody"><span class="tag">${esc(c.category)}</span><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="coursemeta"><span>${done}/${count} complete · ${c.content_kind||(c.lessons?'Authored':'Starter')}</span><a href="#course/${esc(c.id)}">${state.enrolled.includes(c.id)?'Resume':'Open course'} ↗</a></div><div class="progress"><div style="width:${done/count*100}%"></div></div></div></article>`}
function bindBookmarks(){document.querySelectorAll('[data-bookmark]').forEach(b=>b.onclick=()=>{const id=b.dataset.bookmark;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();b.textContent=state.bookmarks.includes(id)?'★':'☆';b.setAttribute('aria-label',(state.bookmarks.includes(id)?'Remove bookmark ':'Bookmark ')+cby(id).title)})}
function stats(){return `<div class="stats">${[[COURSES.length,'Digital courses'],[categories.length,'Skill categories'],[state.enrolled.length,'Enrolled courses'],[Object.values(state.completed).reduce((a,b)=>a+b.length,0),'Completed lessons']].map(([n,t])=>`<div class="stat"><b>${n}</b><span class="muted">${t}</span></div>`).join('')}</div>`}
function home(){const continued=state.enrolled.map(cby).filter(Boolean).slice(0,3);return `<section class="hero"><div><span class="pill">PURPOSEFUL LEARNING. PRACTICAL SKILLS.</span><h1>Your next chapter<br>starts with <em>a new skill.</em></h1><p>Explore ${COURSES.length} digital courses. Read, listen, watch and practise in a workspace built for your progress.</p><div class="actions"><a class="button" href="#catalogue">Explore courses ↗</a><a class="button secondary" href="#learning">My learning</a></div></div><div class="heroart" aria-hidden="true"><div class="orbit"><div class="orbitcore brand-orbit"><img src="assets/ethan-lms-logo.png" alt="" width="190" height="190"></div></div><div class="floating f1">◉ &nbsp; Learn at your pace</div><div class="floating f2">✦ &nbsp; Build real skills</div></div></section>${stats()}<div class="sectionhead"><h2>${continued.length?'Continue your learning':'Start with a digital essential'}</h2><a href="#catalogue">View all courses ↗</a></div><div class="grid">${(continued.length?continued:[cby('c001'),cby('c011'),cby('c031')]).map(card).join('')}</div><div class="sectionhead"><h2>Make learning a habit</h2><a href="#planner">Open study planner →</a></div><div class="modes">${[['Read & PDF','Study notes, print lessons and attach PDF materials.'],['Video & narration','Watch your course media or listen to lesson text.'],['Practice & quizzes','Submit practical work and save assessment results.'],['Plan & reflect','Book study sessions, keep notes and review your progress.']].map(([t,d])=>`<div class="modecard"><b>${t}</b><p>${d}</p></div>`).join('')}</div><div class="notice">All 120 courses include a six-topic course-specific foundation curriculum, a study guide and a narrated overview. Completion here records your learning activity; it is not an accredited qualification.</div>`}
function catalogue(){return `<h1>Find your next digital skill.</h1><p class="muted">Search ${COURSES.length} digital courses across ${categories.length} categories.</p><div class="filters"><input id="search" type="search" placeholder="Search courses…" aria-label="Search courses"><select id="category" aria-label="Course category"><option value="">All categories</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="sort" aria-label="Sort courses"><option value="default">Catalogue order</option><option value="az">Name: A–Z</option><option value="saved">Bookmarked only</option><option value="authored">Authored content only</option></select></div><p id="count" class="muted"></p><div id="results" class="grid"></div>`}
function filter(){const q=$('#search').value.toLowerCase(),cat=$('#category').value,sort=$('#sort').value;let list=COURSES.filter(c=>(!cat||c.category===cat)&&(c.title+' '+c.category).toLowerCase().includes(q)&&(sort!=='saved'||state.bookmarks.includes(c.id))&&(sort!=='authored'||c.content_kind||c.lessons));if(sort==='az')list.sort((a,b)=>a.title.localeCompare(b.title));$('#count').textContent=list.length+' courses found';$('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty">No matching courses. Change the search or filter.</div>';bindBookmarks()}
function learning(){const cs=state.enrolled.map(cby).filter(Boolean);return `<h1>Your learning journey</h1><p class="muted">${user?'Signed-in progress is saved locally and synced to the server.':'Guest progress stays in this browser. Sign in on the account server for shared storage.'}</p>${stats()}<div class="filters"><select id="learningFilter" aria-label="Filter my courses"><option value="all">All enrolled</option><option value="active">In progress</option><option value="done">Completed</option></select></div><div class="grid" id="learningCourses">${cs.map(card).join('')}</div>${cs.length?'':'<div class="empty"><h3>Your next skill is waiting.</h3><a class="button" href="#catalogue">Explore courses</a></div>'}`}
function reading(t){return `<p>${esc(t.intro)}</p><h3>Meaning and core idea</h3><p class="preline">${esc(t.concept)}</p><h3>Practical workflow</h3><ol>${t.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>Worked example / case study</h3><p class="preline">${esc(t.example)}</p><h3>Action point</h3><p class="preline">${esc(t.task)}</p><h3>Mastery review</h3><p>Explain the idea in your own words. Demonstrate your result, test it, and record what you would improve.</p>`}
function course(){const c=current,ls=lessons(c),t=ls[lesson],done=state.completed[c.id]||[];return `<a class="muted" href="#catalogue">← Back to courses</a><div class="sectionhead"><div><span class="tag">${esc(c.category)}</span><h2>${esc(c.title)}</h2></div><div class="actions"><button data-bookmark="${esc(c.id)}" class="secondary">${state.bookmarks.includes(c.id)?'★':'☆'}</button><button id="enrol" class="${state.enrolled.includes(c.id)?'secondary':''}">${state.enrolled.includes(c.id)?'Enrolled ✓':'Enrol'}</button></div></div><div class="lessonlayout"><aside class="lessonnav"><h3>Course pathway</h3><p class="muted">${done.length} of ${ls.length} complete</p><div class="progress"><div style="width:${done.length/ls.length*100}%"></div></div>${ls.map((t,i)=>`<button data-lesson="${i}" class="${i===lesson?'selected':''}">${done.includes(i)?'✓':i+1} &nbsp; ${esc(t.title)}</button>`).join('')}</aside><section class="panel lesson"><span class="tag">${c.lessons?'AUTHORED':'STARTER'} LESSON ${lesson+1} OF ${ls.length}</span><h1>${esc(t.title)}</h1><div class="tabs" role="tablist">${[['read','Read'],['pdf','PDF'],['video','Video'],['narrate','Narrator'],['practice','Practice'],['quiz','Quiz']].map(([m,l])=>`<button role="tab" aria-selected="${mode===m}" data-mode="${m}" class="${mode===m?'selected':''}">${l}</button>`).join('')}</div><div id="modeContent"></div><div class="actions"><button id="complete">${done.includes(lesson)?'Completed ✓':'Complete lesson'}</button>${lesson?'<button id="previous" class="secondary">← Previous</button>':''}${lesson<ls.length-1?'<button id="next" class="secondary">Next →</button>':''}<button id="print" class="secondary">Print / save as PDF</button></div><p class="muted">To complete a lesson, save a practice reflection of at least 20 characters and pass its quiz with 70% or more.</p><div class="actions"><button id="unenrol" class="secondary">Remove from My learning</button><button id="record" class="secondary">Export course record</button></div></section></div>`}
function bindCourse(){bindBookmarks();document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lesson=Number(b.dataset.lesson);state.last[current.id]=lesson;save();renderCourse()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;renderCourse()});$('#enrol').onclick=()=>{if(!state.enrolled.includes(current.id)){state.enrolled.push(current.id);save();renderCourse();toast('Added to My learning')}};$('#complete').onclick=()=>{if((state.notes[noteKey()]||'').trim().length<20||best(current.id,lesson)<70){toast('Save a practice reflection and pass the quiz first.');return}if(!state.enrolled.includes(current.id))state.enrolled.push(current.id);state.completed[current.id]??=[];if(!state.completed[current.id].includes(lesson))state.completed[current.id].push(lesson);save();renderCourse();toast('Lesson completed')};for(const[id,delta]of [['next',1],['previous',-1]])if($('#'+id))$('#'+id).onclick=()=>{lesson+=delta;state.last[current.id]=lesson;save();renderCourse()};$('#print').onclick=()=>{mode='read';renderCourse();requestAnimationFrame(()=>window.print())};$('#unenrol').onclick=()=>{if(confirm('Remove this course from My learning? Your notes and results are kept.')){state.enrolled=state.enrolled.filter(id=>id!==current.id);save();renderCourse()}};$('#record').onclick=()=>download('ETHAN-'+current.id+'-learning-record.json',JSON.stringify({course:current.title,learner:user?.name||state.settings.name,completed:state.completed[current.id]||[],lessons:lessons(current).map((l,i)=>({title:l.title,bestScore:best(current.id,i),reflection:state.notes[current.id+'-'+i]||''})),issued:new Date().toISOString(),notice:'Self-paced learning activity record. Not an accredited or externally verified certificate.'},null,2));showMode()}
function renderCourse(){stopMedia();const token=++renderToken;$('#app').innerHTML=course();bindCourse();return token}
async function showMode(){const token=renderToken,c=current,n=lesson,t=lessons(c)[n],area=$('#modeContent'),k=c.id+'-'+n;const valid=()=>token===renderToken&&current?.id===c.id&&lesson===n;
if(mode==='read')area.innerHTML=reading(t);
if(mode==='narrate'){area.innerHTML=`<h3>Listen to this lesson</h3><p class="muted">Device voices are used. Long lessons are read in short sections.</p><div class="filters"><select id="voice" aria-label="Narrator voice"></select><select id="speed" aria-label="Narration speed"><option value="0.8">0.8×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option></select></div><div class="actions"><button id="speak">▶ Play</button><button id="pause" class="secondary">Pause / resume</button><button id="stop" class="secondary">Stop</button></div><p id="speechStatus" class="muted" role="status"></p><div id="transcript">${reading(t)}</div>`;if(!('speechSynthesis'in window)){$('#speak').disabled=true;$('#speechStatus').textContent='Narration is unavailable in this browser.';return}const voices=()=>{if(valid()&&$('#voice'))$('#voice').innerHTML=speechSynthesis.getVoices().map((v,i)=>`<option value="${i}">${esc(v.name)} (${esc(v.lang)})</option>`).join('')||'<option value="0">Device default voice</option>'};voices();speechSynthesis.onvoiceschanged=voices;$('#speak').onclick=()=>{stopMedia();const run=++speechToken,text=[t.title,t.intro,t.concept,...t.steps,t.example,t.task].join('. '),chunks=text.match(/.{1,220}(?:\s|$)|.{1,220}/g)||[],voice=speechSynthesis.getVoices()[Number($('#voice').value)],rate=Number($('#speed').value);let i=0;function speakNext(){if(!valid()||run!==speechToken)return;if(i>=chunks.length){$('#speechStatus').textContent='Lesson narration finished.';return}$('#speechStatus').textContent=`Reading section ${i+1} of ${chunks.length}`;const u=new SpeechSynthesisUtterance(chunks[i++]);if(voice)u.voice=voice;u.rate=rate;u.onend=speakNext;u.onerror=()=>{if(valid())$('#speechStatus').textContent='Voice playback stopped. Try another device voice.'};window.ethanUtterance=u;speechSynthesis.speak(u)}speakNext()};$('#pause').onclick=()=>speechSynthesis.paused?speechSynthesis.resume():speechSynthesis.pause();$('#stop').onclick=()=>{stopMedia();$('#speechStatus').textContent='Stopped.'}}
if(mode==='practice'){area.innerHTML=`<h3>Practical assignment</h3><p>${esc(t.task)}</p><label class="uploadlabel" for="notes">Project reflection (at least 20 characters)</label><textarea id="notes" placeholder="Describe your work, testing and improvements…">${esc(state.notes[k]||'')}</textarea><div class="actions"><button id="saveNotes">Save reflection</button><button id="submitWork" class="secondary">Submit for review</button></div><label class="uploadlabel">Optional work attachment (PDF, image, TXT or ZIP)<input id="workFile" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.zip"></label><p id="workStatus" class="muted"></p><p class="muted">${user?'Submitted work can be reviewed by an administrator on this server.':'Guest submissions are personal records. Sign in on the account server to request an administrator review.'}</p>`;$('#saveNotes').onclick=()=>{state.notes[k]=$('#notes').value;save();toast('Reflection saved')};$('#workFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>25*1024*1024)throw Error('Maximum attachment size is 25 MB');await resource('put',k+'-work',file);if(valid())$('#workStatus').textContent='Attached: '+file.name}catch(e){toast(e.message)}};$('#submitWork').onclick=async()=>{const text=$('#notes').value.trim();if(text.length<20){toast('Write a reflection of at least 20 characters');return}state.notes[k]=text;save();try{if(user){await api('assignments',{method:'POST',body:JSON.stringify({course_id:c.id,lesson:n,text,file_key:k+'-work'})});toast('Assignment submitted for administrator review')}else{state.assignments.push({id:crypto.randomUUID(),course_id:c.id,lesson:n,text,status:'personal record',created:Date.now()/1000});save();toast('Personal submission saved')}}catch(e){toast(e.message)}}}
if(mode==='quiz'){const qs=t.quiz.map(q=>{const options=q.answers.map((text,index)=>({text,index}));for(let i=options.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[options[i],options[j]]=[options[j],options[i]]}return {...q,options}});area.innerHTML=`<h3>Lesson assessment</h3><p class="muted">Answer all ${qs.length} questions. Pass mark: 70%. Best saved score: ${best(c.id,n)}%.</p><form id="quizForm">${qs.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(q.question)}</legend>${q.options.map(o=>`<label class="quizchoice"><input type="radio" name="q${i}" value="${o.index}" required> ${esc(o.text)}</label>`).join('')}</fieldset>`).join('')}<button>Submit assessment</button></form><div id="feedback" role="status"></div>`;$('#quizForm').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),results=qs.map((q,i)=>Number(form.get('q'+i))===q.correct),score=Math.round(results.filter(Boolean).length/qs.length*100);state.attempts[k]??=[];state.attempts[k].push({score,date:new Date().toISOString()});state.attempts[k]=state.attempts[k].slice(-50);save();$('#feedback').innerHTML=`<h3>${score}% · ${score>=70?'Passed':'Review and retry'}</h3>${qs.map((q,i)=>`<p>${results[i]?'✓':'○'} ${esc(q.question)}<br><strong>Answer:</strong> ${esc(q.answers[q.correct])}<br>${esc(q.explanation||'')}</p>`).join('')}`;$('#quizForm button').disabled=true;const retry=document.createElement('button');retry.textContent='Try again';retry.className='secondary';retry.onclick=()=>showMode();$('#feedback').append(retry)}}
if(mode==='pdf'||mode==='video'){const m=mode,key=k+'-'+m;area.innerHTML=`<h3>${m==='pdf'?'PDF study materials':'Video lesson space'}</h3><p class="muted">Attach your own material${user?' or open published course material':''}. Maximum file size: 25 MB.</p><label class="uploadlabel">Choose ${m==='pdf'?'PDF':'video'}<input id="file" type="file" accept="${m==='pdf'?'application/pdf':'video/mp4,video/webm,video/ogg'}"></label><div id="media"></div><button id="removeResource" class="secondary" hidden>Remove personal resource</button><div id="sharedMedia"></div>`;const display=(f,shared=false)=>{if(!f||!valid())return;const url=URL.createObjectURL(f);objectURLs.push(url);const target=shared?$('#sharedMedia'):$('#media');target.innerHTML=`<h3>${shared?'Published course resource':'Your resource'}</h3><p class="muted">${esc(f.name)}</p>${m==='pdf'?`<iframe title="PDF study material" src="${url}"></iframe>`:`<video controls preload="metadata" src="${url}"></video>`}<a class="button secondary" href="${url}" download="${esc(f.name)}">Download file</a>`;if(!shared)$('#removeResource').hidden=false};try{const f=await resource('get',key);display(f);if(user&&valid())display(await resource('get',key,null,'shared'),true)}catch(e){if(valid())toast(e.message)}if(!valid())return;$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>25*1024*1024)throw Error('Maximum resource size is 25 MB');if(m==='pdf'&&(await file.slice(0,5).text())!=='%PDF-')throw Error('Choose a valid PDF file');if(m==='video'&&!['video/mp4','video/webm','video/ogg'].includes(file.type))throw Error('Choose an MP4, WebM or Ogg video');await resource('put',key,file);display(file);toast('Resource saved')}catch(e){toast(e.message)}};$('#removeResource').onclick=async()=>{try{await resource('delete',key);if(valid()){renderCourse();toast('Resource removed')}}catch(e){toast(e.message)}}}}
function planner(){return `<h1>Make time for your next skill.</h1><p class="muted">Study sessions are shown in your device’s local time. Export them to a calendar app for reminders.</p><form id="planForm" class="panel formgrid"><label>Course<select name="course" required>${COURSES.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('')}</select></label><label>Date and time<input type="datetime-local" name="date" required></label><label>Minutes<input type="number" name="duration" min="10" max="240" value="30" required></label><button>Add study session</button></form><div class="sectionhead"><h2>Your sessions</h2><button id="calendar" class="secondary">Export calendar (.ics)</button></div><div id="sessions"></div>`}
function sessionList(){const list=[...state.plans].sort((a,b)=>a.date.localeCompare(b.date));$('#sessions').innerHTML=list.length?list.map(p=>`<div class="panel session"><div><strong>${esc(cby(p.course)?.title)}</strong><p class="muted">${esc(new Date(p.date).toLocaleString())} · ${p.duration} minutes · ${p.done?'Done':new Date(p.date)<new Date()?'Past session':'Planned'}</p></div><div class="actions"><button data-plan-done="${esc(p.id)}" class="secondary">${p.done?'Mark planned':'Mark done'}</button><button data-plan-remove="${esc(p.id)}" class="secondary">Remove</button></div></div>`).join(''):'<div class="empty">No sessions yet. Add your first study session above.</div>';document.querySelectorAll('[data-plan-done]').forEach(b=>b.onclick=()=>{const p=state.plans.find(p=>p.id===b.dataset.planDone);p.done=!p.done;save();sessionList()});document.querySelectorAll('[data-plan-remove]').forEach(b=>b.onclick=()=>{state.plans=state.plans.filter(p=>p.id!==b.dataset.planRemove);save();sessionList()})}
function calendarExport(){const fmt=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const safe=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ETHAN LMS//Study Planner//EN'];for(const p of state.plans){const start=new Date(p.date);rows.push('BEGIN:VEVENT','UID:'+safe(p.id)+'@ethan-lms','DTSTAMP:'+fmt(new Date()),'DTSTART:'+fmt(start),'DTEND:'+fmt(new Date(start.valueOf()+p.duration*60000)),'SUMMARY:'+safe('Study: '+cby(p.course).title),'DESCRIPTION:Study session planned in ETHAN LMS.','END:VEVENT')}rows.push('END:VCALENDAR');download('ETHAN-LMS-study-plan.ics',rows.join('\r\n')+'\r\n','text/calendar')}
function notebook(){return `<h1>Your learning notebook</h1><div class="filters"><input id="noteSearch" type="search" placeholder="Search your notes…" aria-label="Search notes"></div><div id="noteResults"></div>`}
function noteList(){const q=$('#noteSearch').value.toLowerCase(),entries=Object.entries(state.notes).filter(([k,v])=>v.trim()&&(v+' '+cby(k.replace(/-\d+$/,''))?.title).toLowerCase().includes(q));$('#noteResults').innerHTML=entries.length?entries.map(([k,v])=>{const id=k.replace(/-\d+$/,''),n=Number(k.match(/\d+$/)[0]),c=cby(id);return `<article class="panel note"><span class="tag">${esc(c?.title||id)} · Lesson ${n+1}</span><p class="preline">${esc(v)}</p><a class="button secondary" href="#course/${esc(id)}/${n}/practice">Open reflection</a></article>`}).join(''):'<div class="empty">No matching notes. Save a reflection in a course’s Practice mode.</div>'}
function resources(){return `<h1>Resource studio</h1><div class="panel"><h3>Protect your learning record</h3><p>Export enrolments, progress, assessments, reflections, bookmarks and study sessions. Download attached media separately from the list below.</p><div class="actions"><button id="export">Export backup</button><label class="button secondary">Restore backup<input id="restore" type="file" accept="application/json" hidden></label></div><p class="muted">Backup excludes media files and course authoring. Course editor exports are separate.</p></div><div class="sectionhead"><h2>Attached resources</h2><button id="refreshFiles" class="secondary">Refresh</button></div><div id="resourceList" class="panel">Loading resources…</div>`}
async function fileList(){const token=renderToken;try{const files=user?(await api('files')).files:await localResource('list');if(token!==renderToken||!$('#resourceList'))return;$('#resourceList').innerHTML=files.length?files.map((f,i)=>`<div class="resourceRow"><div><strong>${esc(f.name)}</strong><p class="muted">${esc(f.key)} · ${(f.size/1024/1024).toFixed(2)} MB ${f.owner==='shared'?'· Published':''}</p></div><div class="actions"><button data-file-download="${i}" class="secondary">Download</button>${f.owner==='shared'?'':`<button data-file-delete="${i}" class="secondary">Delete</button>`}</div></div>`).join(''):'<p>No attached resources. Add a PDF, video or project file inside a course.</p>';document.querySelectorAll('[data-file-download]').forEach(b=>b.onclick=async()=>{const f=files[Number(b.dataset.fileDownload)];try{const blob=await resource('get',f.key,null,f.owner==='shared'?'shared':'');if(blob)download(f.name,blob);else toast('Resource no longer exists')}catch(e){toast(e.message)}});document.querySelectorAll('[data-file-delete]').forEach(b=>b.onclick=async()=>{const f=files[Number(b.dataset.fileDelete)];if(confirm('Delete '+f.name+'?'))try{await resource('delete',f.key);fileList()}catch(e){toast(e.message)}})}catch(e){if($('#resourceList'))$('#resourceList').textContent='Resource storage unavailable: '+e.message}}
function settings(){return `<h1>Your learning preferences</h1><form id="settingsForm" class="panel formgrid"><label>Display name<input name="name" maxlength="120" value="${esc(state.settings.name)}" required></label><label>Theme<select name="theme"><option value="light">Light</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Dark</option></select></label><label>Lesson text size<select name="font">${[16,18,20].map(n=>`<option ${state.settings.font===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Preferred learning mode<select name="mode">${['read','pdf','video','narrate','practice','quiz'].map(m=>`<option value="${m}" ${state.settings.mode===m?'selected':''}>${m[0].toUpperCase()+m.slice(1)}</option>`).join('')}</select></label><button>Save preferences</button></form><div class="panel note"><h3>Support and contact</h3><p>Questions about Ethan Digital Academy training?</p><a class="button" target="_blank" rel="noopener" href="https://wa.me/2348064656499?text=${encodeURIComponent('Hello Ethan Digital Academy, I need assistance with ETHAN LMS.')}" >Contact on WhatsApp</a> <a class="button secondary" href="mailto:ethandigitalacademy@gmail.com">Email Ethan</a></div>`}
function account(){if(user)return `<h1>Your account</h1><div class="panel"><h3>${esc(user.name)}</h3><p>${esc(user.email)} · ${esc(user.role)}</p><p>Your learning record is synced to this account server. Personal media is stored separately on the server.</p><button id="logout">Sign out</button><p class="muted">Manage email verification and course access from your account and payments pages.</p></div>`;if(!server)return `<h1>Account workspace</h1><div class="panel"><h3>You are using guest mode.</h3><p>Start the account-enabled app with <code>python app.py</code> and open its local address to enable registration, sign-in, shared resources and administrator review.</p><p>Guest notes and progress stay on this browser. Export a backup before moving to another device.</p><a class="button" href="#resources">Export your record</a></div>`;return `<h1>Keep your learning with you.</h1><div class="grid accountgrid"><form id="loginForm" class="panel formgrid"><h3>Sign in</h3><label>Email<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" minlength="10" maxlength="256" autocomplete="current-password" required></label><button>Sign in</button><p class="muted">Forgotten passwords can be reset by the server operator. Email reset is not configured.</p></form><form id="registerForm" class="panel formgrid"><h3>Create account</h3><label>Full name<input name="name" maxlength="120" autocomplete="name" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" minlength="10" maxlength="256" autocomplete="new-password" required></label><button>Create account</button><p class="muted">At least 10 characters. New accounts are students.</p></form></div>`}
async function signIn(action,form){const button=form.querySelector('button');button.disabled=true;try{await saveQueue.catch(()=>{});const b=Object.fromEntries(new FormData(form));const response=await api(action,{method:'POST',body:JSON.stringify(b)});user=response.user;const remote=await api('state');state=remote.state?cleanState(remote.state):blank();state.settings.name=user.name;applySettings();save();updateProfile();route();toast('Signed in successfully')}catch(e){toast(e.message);button.disabled=false}}
function assignments(){return `<h1>Assignments and feedback</h1><p class="muted">${user?.role==='admin'?'Review student work and provide a score and feedback.':user?'Track submissions and administrator feedback.':'Guest submissions are personal records; they are not sent to an instructor.'}</p><div id="assignmentList" class="panel">Loading submissions…</div>`}
async function assignmentList(){const token=renderToken;try{const list=user?(await api('assignments')).assignments:state.assignments;if(token!==renderToken)return;$('#assignmentList').innerHTML=list.length?list.map((a,i)=>`<article class="assignment"><span class="tag">${esc(cby(a.course_id)?.title||a.course_id)} · Lesson ${a.lesson+1}</span><h3>${esc(a.status)}${a.score==null?'':` · ${a.score}%`}</h3>${user?.role==='admin'?`<p class="muted">${esc(a.name)} · ${esc(a.email)}</p>`:''}<p class="preline">${esc(a.text)}</p>${a.feedback?`<p><strong>Feedback:</strong> ${esc(a.feedback)}</p>`:''}${a.file_key&&user?`<button data-assignment-file="${i}" class="secondary">Download attachment if provided</button>`:''}${user?.role==='admin'?`<form data-review="${esc(a.id)}" class="formgrid"><label>Score (0–100)<input type="number" name="score" min="0" max="100" value="${a.score??''}" required></label><label>Feedback<textarea name="feedback" required maxlength="5000">${esc(a.feedback)}</textarea></label><button>Save review</button></form>`:''}</article>`).join(''):'<p>No submissions yet. Open a course and submit work in Practice mode.</p>';document.querySelectorAll('[data-review]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(f));b.score=Number(b.score);await api('assignments/'+f.dataset.review,{method:'PUT',body:JSON.stringify(b)});toast('Review saved');assignmentList()}catch(e){toast(e.message)}});document.querySelectorAll('[data-assignment-file]').forEach(b=>b.onclick=async()=>{const a=list[Number(b.dataset.assignmentFile)];try{const f=await resource('get',a.file_key,null,user.role==='admin'?a.user_id:'');if(f)download(f.name,f);else toast('No attachment was submitted')}catch(e){toast(e.message)}})}catch(e){if($('#assignmentList'))$('#assignmentList').textContent=e.message}}
function validCourse(v){if(!v||typeof v!=='object'||['__proto__','constructor','prototype'].includes(v.id)||! /^[a-zA-Z0-9_-]{1,64}$/.test(v.id)||!categories.includes(v.category))throw Error('Use a valid ID and digital course category');for(const k of ['title','description','project'])if(typeof v[k]!=='string'||!v[k].trim()||v[k].length>(k==='title'?160:2000))throw Error('Provide course '+k);if(!Array.isArray(v.lessons)||v.lessons.length<1||v.lessons.length>30)throw Error('Provide 1–30 lessons');for(const l of v.lessons){for(const k of ['title','intro','concept','example','task'])if(typeof l[k]!=='string'||!l[k].trim()||l[k].length>20000)throw Error('Provide lesson '+k);if(!Array.isArray(l.steps)||!l.steps.length||l.steps.length>20||l.steps.some(s=>typeof s!=='string'||s.length>3000))throw Error('Provide workflow steps');if(!Array.isArray(l.quiz)||!l.quiz.length||l.quiz.length>20)throw Error('Provide 1–20 quiz questions');for(const q of l.quiz)if(!q||typeof q.question!=='string'||!q.question.trim()||q.question.length>2000||!Array.isArray(q.answers)||q.answers.length<2||q.answers.length>6||q.answers.some(a=>typeof a!=='string'||a.length>2000)||!Number.isInteger(q.correct)||q.correct<0||q.correct>=q.answers.length)throw Error('Quiz questions need choices and a valid correct-answer index')}
return {id:v.id,title:v.title,category:v.category,description:v.description,project:v.project,lessons:v.lessons,level:'Foundation',color:'#e9f1ff'}}
function studio(){if(server&&user?.role!=='admin')return '<h1>Course studio</h1><div class="panel">Sign in with an administrator account to manage shared course content. <a class="button" href="#account">Account</a></div>';return `<h1>Course studio</h1><p class="muted">${user?'Administrator changes are published to this server.':'Local authoring workspace. Changes affect this browser; export courses for transfer.'}</p><div class="filters"><select id="editCourse" aria-label="Choose course to edit">${COURSES.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('')}</select><button id="newCourse" class="secondary">Add digital course</button><button id="exportCourses" class="secondary">Export authored courses</button><label class="button secondary">Import course JSON<input id="importCourses" type="file" accept="application/json" hidden></label></div><form id="courseForm" class="panel formgrid"><label>Course ID<input id="courseId" required pattern="[a-zA-Z0-9_-]{1,64}"></label><label>Course title<input id="courseTitle" maxlength="160" required></label><label>Digital category<select id="courseCategory">${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Description<textarea id="courseDescription" maxlength="2000" required></textarea></label><label>Portfolio project<textarea id="courseProject" maxlength="2000" required></textarea></label><h3>Lessons</h3><div id="lessonEditors"></div><button type="button" id="addLesson" class="secondary">Add lesson</button><button>Save ${user?'and publish':'locally'}</button></form>${user?'<section class="panel note"><h3>Publish course media</h3><p>Select a saved course above, then a lesson and PDF or video. Students can access published media when signed in.</p><div class="filters"><select id="mediaLesson" aria-label="Media lesson"></select><select id="mediaType" aria-label="Resource type"><option value="pdf">PDF</option><option value="video">Video</option></select><input id="publishFile" type="file" accept="application/pdf,video/mp4,video/webm,video/ogg"></div><button id="publishMedia">Upload published resource</button><button id="deletePublished" class="secondary">Remove published resource</button></section>':''}`}
let editorLessons=[];
function editorFields(){const el=$('#lessonEditors');el.innerHTML=editorLessons.map((l,i)=>`<fieldset class="editorLesson"><legend>Lesson ${i+1}</legend>${[['title','Title'],['intro','Introduction / objectives'],['concept','Detailed notes / meaning'],['example','Worked example / case study'],['task','Practical task']].map(([k,label])=>`<label>${label}<textarea data-field="${k}" data-index="${i}" required>${esc(l[k])}</textarea></label>`).join('')}<label>Workflow (one step per line)<textarea data-field="steps" data-index="${i}" required>${esc(l.steps.join('\n'))}</textarea></label><label>Assessment JSON<textarea data-field="quiz" data-index="${i}" required>${esc(JSON.stringify(l.quiz,null,2))}</textarea></label><p class="muted">Each question uses question, answers (array), correct (zero-based index), and explanation. Example: {"question":"Which tag is a heading?","answers":["h1","p"],"correct":0,"explanation":"h1 defines the main heading."}</p><button type="button" data-remove-lesson="${i}" class="secondary">Remove lesson</button></fieldset>`).join('');document.querySelectorAll('[data-remove-lesson]').forEach(b=>b.onclick=()=>{try{captureEditor();if(editorLessons.length<2)throw Error('Keep at least one lesson');editorLessons.splice(Number(b.dataset.removeLesson),1);editorFields()}catch(e){toast(e.message)}})}
function captureEditor(){document.querySelectorAll('[data-field]').forEach(e=>{const i=Number(e.dataset.index),k=e.dataset.field;editorLessons[i][k]=k==='quiz'?JSON.parse(e.value):k==='steps'?e.value.split('\n').filter(s=>s.trim()):e.value})}
function fillEditor(c){$('#courseId').value=c.id;$('#courseTitle').value=c.title;$('#courseCategory').value=c.category;$('#courseDescription').value=c.description;$('#courseProject').value=c.project;editorLessons=structuredClone(lessons(c));editorFields();if($('#mediaLesson'))$('#mediaLesson').innerHTML=editorLessons.map((l,i)=>`<option value="${i}">Lesson ${i+1}: ${esc(l.title)}</option>`).join('')}
async function publishCourse(c){c={...(cby(c.id)||{}),...validCourse(c)};if(user)await api('courses',{method:'PUT',body:JSON.stringify(c)});else{let local=[];try{local=JSON.parse(localStorage.getItem('ethan-lms-authored')||'[]')}catch{}local=local.filter(x=>x.id!==c.id);local.push(c);localStorage.setItem('ethan-lms-authored',JSON.stringify(local))}const i=COURSES.findIndex(x=>x.id===c.id);if(i<0)COURSES.push(c);else COURSES[i]=c;return c}
function reports(){if(user?.role!=='admin')return '<h1>Learning report</h1><div id="personalReport" class="panel"></div>';return '<h1>Administrator report</h1><p class="muted">Progress and quiz marks are learner activity records. Assignment scores are administrator-reviewed.</p><div id="adminReport" class="panel">Loading…</div><button id="reportCSV" class="secondary">Export learner report CSV</button>'}
function reportRows(users,states){return users.map(u=>{const s=cleanState(states[u.id]);return {name:u.name,email:u.email,role:u.role,enrolled:s.enrolled.length,lessons:Object.values(s.completed).reduce((n,a)=>n+a.length,0),assessments:Object.values(s.attempts).reduce((n,a)=>n+a.length,0)}})}
let reportData=[];
async function bindReports(){if(user?.role==='admin'){const r=await api('report');reportData=reportRows(r.users,r.states);if(!$('#adminReport'))return;$('#adminReport').innerHTML=`<div class="tablewrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Courses</th><th>Lessons</th><th>Attempts</th></tr></thead><tbody>${reportData.map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('#reportCSV').onclick=()=>{const quote=v=>'"'+String(v).replace(/"/g,'""').replace(/^[\s]*[=+@-]/,"'")+'"';download('ETHAN-LMS-learner-report.csv',[['Name','Email','Role','Enrolled','Completed lessons','Assessment attempts'],...reportData.map(Object.values)].map(row=>row.map(quote).join(',')).join('\r\n'),'text/csv')}}else $('#personalReport').innerHTML=`<h3>${esc(user?.name||state.settings.name)}</h3>${stats()}<p>${Object.values(state.attempts).reduce((n,a)=>n+a.length,0)} assessment attempts recorded.</p><a class="button" href="#resources">Export full learning record</a>`}
function updateProfile(){$('.profile').innerHTML=`<a class="status" href="#account">${user?'● '+esc(user.name)+' · '+esc(user.role):server?'● Guest · Sign in':'● Guest workspace'}</a><a class="avatar" href="#settings">${esc((user?.name||state.settings.name).split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase())}</a>`}
async function route(){stopMedia();renderToken++;const parts=(location.hash.slice(1)||'home').split('/');view=parts[0];document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===view||(view==='course'&&a.dataset.nav==='catalogue')));$('#pageTitle').textContent=({home:'Overview',catalogue:'Explore courses',learning:'My learning',resources:'Resources',course:'Course workspace',planner:'Study planner',notebook:'Notebook',settings:'Preferences',account:'Account',studio:'Course studio',assignments:'Assignments',reports:'Reports'})[view]||'Overview';if(view==='course'){current=cby(parts[1]);if(!current){$('#app').innerHTML='<div class="empty">Course not found. <a href="#catalogue">Browse courses</a></div>';return}const max=lessons(current).length;lesson=/^\d+$/.test(parts[2]||'')?Math.min(max-1,Number(parts[2])):state.last[current.id]||0;lesson=Math.min(max-1,lesson);mode=['read','pdf','video','narrate','practice','quiz'].includes(parts[3])?parts[3]:state.settings.mode;renderCourse();return}current=null;$('#app').innerHTML=({home,catalogue,learning,resources,planner,notebook,settings,account,studio,assignments,reports}[view]||home)();bindBookmarks();if(view==='catalogue'){filter();$('#search').oninput=filter;$('#category').onchange=filter;$('#sort').onchange=filter}if(view==='learning')$('#learningFilter').onchange=()=>{const v=$('#learningFilter').value;$('#learningCourses').innerHTML=state.enrolled.map(cby).filter(Boolean).filter(c=>v==='all'||(v==='done')===((state.completed[c.id]||[]).length===lessons(c).length)).map(card).join('');bindBookmarks()};if(view==='planner'){sessionList();$('#planForm').onsubmit=e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));if(!Number.isFinite(new Date(p.date).valueOf())){toast('Choose a valid date');return}state.plans.push({...p,id:crypto.randomUUID(),duration:Number(p.duration),done:false});save();sessionList();toast('Study session added')};$('#calendar').onclick=calendarExport}if(view==='notebook'){noteList();$('#noteSearch').oninput=noteList}if(view==='settings')$('#settingsForm').onsubmit=e=>{e.preventDefault();const s=Object.fromEntries(new FormData(e.target));s.font=Number(s.font);state.settings=s;applySettings();save();updateProfile();toast('Preferences saved')};if(view==='resources'){fileList();$('#refreshFiles').onclick=fileList;$('#export').onclick=()=>download('ETHAN-LMS-v3-backup.json',JSON.stringify(state,null,2));$('#restore').onchange=async e=>{try{const raw=JSON.parse(await e.target.files[0].text());if(!raw||!Array.isArray(raw.enrolled)||!raw.completed||!raw.notes)throw Error('Invalid learning backup');const clean=cleanState(raw);if(confirm('Replace your current progress, notes, assessments and planner with this backup? Media files are kept.')){state=clean;save();applySettings();updateProfile();toast('Backup restored')}}catch(e){toast(e.message)}}}if(view==='account'){for(const[action,id]of [['login','loginForm'],['register','registerForm']])if($('#'+id))$('#'+id).onsubmit=e=>{e.preventDefault();signIn(action,e.target)};if($('#logout'))$('#logout').onclick=async()=>{try{await saveQueue;await api('logout',{method:'POST',body:'{}'});user=null;loadState();updateProfile();route();toast('Signed out')}catch(e){toast(e.message)}}}if(view==='assignments')assignmentList();if(view==='reports')try{await bindReports()}catch(e){toast(e.message)}if(view==='studio'&&$('#courseForm')){fillEditor(COURSES[0]);$('#editCourse').onchange=e=>fillEditor(cby(e.target.value));$('#newCourse').onclick=()=>fillEditor({id:'digital-'+Date.now(),title:'New digital course',category:categories[0],description:'Describe the digital skill and learning outcomes.',project:'Describe the final practical project.'});$('#addLesson').onclick=()=>{try{captureEditor();if(editorLessons.length>=30)throw Error('Maximum 30 lessons');editorLessons.push(structuredClone(editorLessons[0]));editorLessons.at(-1).title='New lesson';editorFields()}catch(e){toast('Fix the assessment JSON before adding a lesson: '+e.message)}};$('#courseForm').onsubmit=async e=>{e.preventDefault();try{captureEditor();await publishCourse({id:$('#courseId').value,title:$('#courseTitle').value,category:$('#courseCategory').value,description:$('#courseDescription').value,project:$('#courseProject').value,lessons:editorLessons});toast('Course saved');route()}catch(e){toast(e.message)}};$('#exportCourses').onclick=()=>download('ETHAN-LMS-authored-courses.json',JSON.stringify(COURSES.filter(c=>c.lessons),null,2));$('#importCourses').onchange=async e=>{try{const raw=JSON.parse(await e.target.files[0].text()),list=Array.isArray(raw)?raw:[raw];if(list.length>200)throw Error('Maximum 200 courses per import');const valid=list.map(validCourse);if(!confirm('Import '+valid.length+' courses? Matching course IDs will be replaced.'))return;for(const c of valid)await publishCourse(c);toast('Imported '+valid.length+' courses');route()}catch(e){toast(e.message)}};if($('#publishMedia')){$('#publishMedia').onclick=async()=>{const cid=$('#editCourse').value,n=$('#mediaLesson').value,type=$('#mediaType').value,file=$('#publishFile').files[0];if(!file){toast('Choose a PDF or video file');return}try{if(type==='pdf'&&(await file.slice(0,5).text())!=='%PDF-')throw Error('Choose a valid PDF');if(type==='video'&&!file.type.startsWith('video/'))throw Error('Choose a video file');await resource('put',cid+'-'+n+'-'+type,file,'shared');toast('Course resource published')}catch(e){toast(e.message)}};$('#deletePublished').onclick=async()=>{if(confirm('Remove the published resource for this lesson and mode?'))try{await resource('delete',$('#editCourse').value+'-'+$('#mediaLesson').value+'-'+$('#mediaType').value,null,'shared');toast('Published resource removed')}catch(e){toast(e.message)}}}}window.scrollTo(0,0)}
async function init(){loadState();try{const r=await api('health');server=!!r.server;if(server){const shared=await api('courses');for(const c of shared.courses){try{const v=validCourse(c),i=COURSES.findIndex(x=>x.id===v.id);if(i<0)COURSES.push(v);else COURSES[i]={...COURSES[i],...v}}catch{}}user=(await api('me')).user;if(user){const remote=await api('state');state=remote.state?cleanState(remote.state):blank();state.settings.name=user.name;applySettings();save()}}}catch{server=false}if(!server){try{const cs=JSON.parse(localStorage.getItem('ethan-lms-authored')||'[]');for(const c of cs){const v=validCourse(c),i=COURSES.findIndex(x=>x.id===v.id);if(i<0)COURSES.push(v);else COURSES[i]={...COURSES[i],...v}}}catch{}loadState()}updateProfile();window.addEventListener('hashchange',()=>route().catch(e=>toast(e.message)));await route();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});window.addEventListener('online',()=>{if(user)save()})}
init().catch(e=>{state??=blank();toast('Could not initialise workspace: '+e.message)});
